    for m in (attempt("list_event_source_mappings", lam.list_event_source_mappings) or {}).get("EventSourceMappings", []):
        src = m.get("EventSourceArn", "")
        if src.rsplit(":", 1)[-1].startswith(PREFIX + "-"):
